import hashlib,json,secrets
from pathlib import Path
from datetime import datetime,timezone
root=Path(__file__).resolve().parents[2]
path=root/'experiments/plans/levels-factorial.json'
assert not path.exists()
base=json.loads((root/'experiments/final-config.json').read_text())
variants={'control':base,'economics':{**base,'fee':.72,'margin':.05,'trustStep':0},'admission':{**base,'capacity':.85,'backlog':.4,'sameDayBacklog':12,'maxKm':900,'minDrivers':4},'coupled':{**base,'fee':.72,'margin':.05,'trustStep':0,'capacity':.85,'backlog':.4,'sameDayBacklog':12,'maxKm':900,'minDrivers':4}}
seeds=['levels-development-'+secrets.token_hex(10) for _ in range(3)]
trials=[{'level':level,'seed':seed,'settings':settings,'label':'levels-factorial-'+label} for seed in seeds for level in [1,4,7] for label,settings in variants.items()]
plan={'frozenAt':datetime.now(timezone.utc).isoformat(),'role':'development only; no promotion or ranking based on this panel','revision':'bdaec082250da2c16cbc862142e37a00feca4740e6fc59db846de37380f6ed39','attempts':'experiments/levels-factorial-attempts.jsonl','report':'docs/levels-factorial.json','seeds':seeds,'levels':[1,4,7],'variants':variants,'trials':trials,'unit':'Three unique seed blocks. Each block is repeated across three levels and four policies. Thirty-six worlds are not thirty-six independent weeks. Level2/3 share worlds and are not substituted for independent evidence.','contrasts':{'economics':'Changes fee assumption, driver pay and quote floor together; removes trust premium absent belowlevel8. This does not isolate a pure payment effect.','admission':'Changes regional daily capacity, backlog, same-day capacity, route length and minimum supply together.','interaction':'coupled - economics - admission + control, calculated within each level and seed.','levelSelection':'Levels1,4,7 are distinct mechanism regimes: price ignored; competitive quotes with abundant supply; competitive quotes with scarce supply. Results do not validate omitted levels2,3,5,6.'},'hypotheses':[{'name':'economic mismatch','mechanism':'Lower the public typical-fee estimate and resulting customer quote floor in a world where there is ample driver supply; belowlevel8 do not price in a trust bonus that does not exist.','falsifiedBy':'Economics arm fails to increase net margin, or lower pay increases late rescue cost/refunds enough to erase it.'},{'name':'admission bottleneck','mechanism':'Broaden the scarcity limits to admit viable jobs that the level8 controller rejects.','falsifiedBy':'Extra admitted work lowers profit or reliability, or brings negligible throughput.'},{'name':'complementarity','mechanism':'Broader admission creates volume while lower pay and quotes make those jobs profitable.','falsifiedBy':'Coupled gain fails to exceed the sum of separate gains, or qualification fails. A positive interaction alone is not a promotion criterion.'}],'screeningGatePerLevel':{'meanPairedGainEurosAtLeast':1500,'minimumPairedGainEurosAtLeast':0,'allWeeksQualified':True,'minimumWeeklyOnTimeShare':.92,'undeliveredOrders':0,'failedVisits':0},'selection':'Complete all36trials and retain every result. No parameter tuning inside panel. Candidate eligibility requires all screen gates at the relevant level; choose highest mean net gain among passing predeclared variants, tie by higher worst on-time share. Development selection is exploratory, not confirmatory. No pooling strong abundant-level gains to conceal a shortage-level loss.','independentValidation':'A selected candidate requires a new complete frozen untouched panel under experiments/search-integrity.json before any promotion. Validation must cover each intended level; a small favorable level subset cannot authorize alllevels. No standards relaxed to fit09:00 cutoff.','deadline':'No further ranking based on this development panel; no ranked action after2026-11-14T07:00:00Z. Unranked development may continue after deadline.','interruptions':'Retain attempted failures; stop new creates on runner error. No poor-week deletion or silent replacement.','sourceFiles':{str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((root/'research/ranked-levels/bundle').rglob('*')) if p.is_file()}}
path.write_text(json.dumps(plan,indent=2)+'\n')
print(json.dumps({'trials':len(trials),'uniqueSeedBlocks':len(seeds),'levels':plan['levels'],'developmentOnly':True}))
